import{_ as o,o as s,c as e,ag as r}from"./chunks/framework.BZohXCq9.js";const h=JSON.parse('{"title":"Admin Payment Stats – What They Mean","description":"","frontmatter":{},"headers":[],"relativePath":"ADMIN_PAYMENT_STATS_EXPLAINED.md","filePath":"ADMIN_PAYMENT_STATS_EXPLAINED.md"}'),n={name:"ADMIN_PAYMENT_STATS_EXPLAINED.md"};function a(i,t,l,d,g,u){return s(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="admin-payment-stats-–-what-they-mean" tabindex="-1">Admin Payment Stats – What They Mean <a class="header-anchor" href="#admin-payment-stats-–-what-they-mean" aria-label="Permalink to &quot;Admin Payment Stats – What They Mean&quot;">​</a></h1><p>This doc explains <strong>what “gross receipt” is</strong>, <strong>what each stat</strong> on the admin Payment Management page represents, and <strong>how the numbers are built</strong> from your transaction ledger.</p><hr><h2 id="_1-what-is-gross-receipt" tabindex="-1">1. What is “Gross receipt”? <a class="header-anchor" href="#_1-what-is-gross-receipt" aria-label="Permalink to &quot;1. What is “Gross receipt”?&quot;">​</a></h2><p><strong>Gross receipt</strong> = the <strong>full amount</strong> that a student paid for a lesson (or set of lessons) in a single payment.</p><ul><li>When a student pays <strong>90 CHF</strong> for one lesson, that <strong>90 CHF</strong> is one “gross receipt” for the platform.</li><li>The platform does <strong>not</strong> keep all of it: part goes to the <strong>instructor</strong> (instructor share) and part stays with the <strong>platform</strong> (commission). “Gross” means “before splitting”; the <strong>net</strong> the platform keeps is the commission (e.g. 20% of 90 = 18 CHF).</li></ul><p>So in your system:</p><ul><li><strong>“Platform gross receipt”</strong> = one ledger line per successful payment, for the <strong>full payment amount</strong> (same as “what the customer paid”).</li><li><strong>“Platform commission”</strong> = a <strong>separate</strong> ledger line for the platform’s <strong>share only</strong> (e.g. 20% of that payment).</li></ul><p>We use “gross receipt” in the <strong>Total earned</strong> stat so that number matches <strong>Stripe’s “Gross volume”</strong> (total amount paid by customers), and we <strong>don’t</strong> add “Platform commission” again (that would double-count).</p><hr><h2 id="_2-what-stats-you-show-summary" tabindex="-1">2. What stats you show (summary) <a class="header-anchor" href="#_2-what-stats-you-show-summary" aria-label="Permalink to &quot;2. What stats you show (summary)&quot;">​</a></h2><p>On <strong>Payment Management</strong> you show five summary stats at the top:</p><table tabindex="0"><thead><tr><th>Stat label</th><th>What it is</th><th>How it’s calculated</th></tr></thead><tbody><tr><td><strong>Total earned</strong></td><td>Total <strong>payment volume</strong> (same idea as Stripe “Gross volume”)</td><td>Sum of all <strong>“Platform gross receipt”</strong> transaction amounts (one per successful payment).</td></tr><tr><td><strong>Payments</strong></td><td>Number of <strong>payment events</strong> (student paid for a lesson / booking)</td><td>Count of transactions with <code>type === &quot;payment&quot;</code>.</td></tr><tr><td><strong>Refunds</strong></td><td>Number of <strong>refund events</strong> (admin approved a refund for a cancelled slot)</td><td>Count of transactions with <code>type === &quot;refund&quot;</code>.</td></tr><tr><td><strong>Payouts</strong></td><td>Number of <strong>payout events</strong> (money sent to instructor’s bank)</td><td>Count of transactions with <code>type === &quot;payout&quot;</code>.</td></tr><tr><td><strong>Transactions</strong></td><td>Total number of <strong>all</strong> ledger entries (payments, refunds, payouts, etc.)</td><td>Count of all succeeded transactions.</td></tr></tbody></table><p>So:</p><ul><li><strong>Total earned</strong> = <strong>money</strong> (CHF): total of “gross receipt” lines → matches Stripe’s gross volume.</li><li><strong>Payments / Refunds / Payouts</strong> = <strong>counts</strong> (how many of each event).</li><li><strong>Transactions</strong> = <strong>count</strong> of every line in the ledger.</li></ul><hr><h2 id="_3-what-total-earned-is-and-what-it-is-not" tabindex="-1">3. What “Total earned” is (and what it is not) <a class="header-anchor" href="#_3-what-total-earned-is-and-what-it-is-not" aria-label="Permalink to &quot;3. What “Total earned” is (and what it is not)&quot;">​</a></h2><ul><li><p><strong>It is:</strong> Total amount <strong>received from students</strong> for lessons (sum of each payment’s full amount).<br> That’s why we base it only on <strong>“Platform gross receipt”</strong> and not on commission.</p></li><li><p><strong>It is not:</strong></p><ul><li>The <strong>platform’s profit</strong> (profit = commission only).</li><li><strong>Net</strong> after refunds (we don’t subtract refunds from this stat).</li><li>Instructor share (that money is transferred to instructors; we only “pass it through”).</li></ul></li></ul><p>So: <strong>Total earned</strong> = <strong>Gross payment volume</strong> (same concept as Stripe’s “Gross volume” 360 CHF in your example).</p><hr><h2 id="_4-what-s-in-the-ledger-transaction-types-and-roles" tabindex="-1">4. What’s in the ledger (transaction types and roles) <a class="header-anchor" href="#_4-what-s-in-the-ledger-transaction-types-and-roles" aria-label="Permalink to &quot;4. What’s in the ledger (transaction types and roles)&quot;">​</a></h2><p>For every <strong>payment</strong> (student pays for a lesson), we create <strong>several</strong> transaction rows (roles = student, platform, instructor). That’s why <strong>Transactions</strong> (count) is higher than <strong>Payments</strong> (count).</p><h3 id="when-a-student-pays-90-chf-one-lesson-20-commission" tabindex="-1">When a student pays 90 CHF (one lesson, 20% commission) <a class="header-anchor" href="#when-a-student-pays-90-chf-one-lesson-20-commission" aria-label="Permalink to &quot;When a student pays 90 CHF (one lesson, 20% commission)&quot;">​</a></h3><p>We create for example:</p><table tabindex="0"><thead><tr><th>Type</th><th>Role</th><th>Direction</th><th>Amount</th><th>Description (idea)</th></tr></thead><tbody><tr><td>payment</td><td>student</td><td>debit</td><td>90</td><td>Student paid for lesson</td></tr><tr><td>payment</td><td>platform</td><td>credit</td><td>90</td><td><strong>Platform gross receipt</strong> (full 90)</td></tr><tr><td>payment</td><td>instructor</td><td>credit</td><td>72</td><td>Instructor share (80%)</td></tr><tr><td>payment</td><td>platform</td><td>credit</td><td>18</td><td><strong>Platform commission</strong> (20%)</td></tr></tbody></table><ul><li><strong>Gross receipt</strong> = the one <strong>platform credit</strong> line with “gross receipt” in the description (the 90).</li><li><strong>Commission</strong> = the other platform credit (the 18). We do <strong>not</strong> add this again into “Total earned”.</li></ul><p>So:</p><ul><li><strong>Total earned</strong> = sum of all “Platform gross receipt” amounts (e.g. 90 + 90 + … = 360).</li><li><strong>Payments</strong> = number of payment events (e.g. 14).</li><li><strong>Transactions</strong> = number of all lines (e.g. 14 × 4 + refund lines + payout lines + … = 21 or whatever you see).</li></ul><hr><h2 id="_5-other-transaction-types-refunds-payouts" tabindex="-1">5. Other transaction types (refunds, payouts) <a class="header-anchor" href="#_5-other-transaction-types-refunds-payouts" aria-label="Permalink to &quot;5. Other transaction types (refunds, payouts)&quot;">​</a></h2><ul><li><p><strong>Refund (admin approved)</strong><br> We create e.g. student <strong>credit</strong> (money back), instructor <strong>debit</strong> (reversal of their share), platform <strong>debit</strong> (commission reversed).<br><strong>Refunds</strong> stat = count of <code>type === &quot;refund&quot;</code>.</p></li><li><p><strong>Payout (to instructor’s bank)</strong><br> We create e.g. instructor <strong>credit</strong> (payout to bank).<br><strong>Payouts</strong> stat = count of <code>type === &quot;payout&quot;</code>.</p></li></ul><p>These don’t change <strong>Total earned</strong> in the current design; Total earned is only the sum of “Platform gross receipt” (gross volume).</p><hr><h2 id="_6-short-glossary" tabindex="-1">6. Short glossary <a class="header-anchor" href="#_6-short-glossary" aria-label="Permalink to &quot;6. Short glossary&quot;">​</a></h2><ul><li><strong>Gross receipt</strong> = Full payment amount received from the customer (one such ledger line per payment). Used for “Total earned” so it matches Stripe gross volume.</li><li><strong>Commission</strong> = Platform’s share of that payment (e.g. 20%). Stored as a separate “Platform commission” transaction; not added again into Total earned.</li><li><strong>Total earned (admin)</strong> = Sum of all “Platform gross receipt” amounts = <strong>gross payment volume</strong> (same idea as Stripe “Gross volume”).</li><li><strong>Payments</strong> = Number of successful payment events.</li><li><strong>Refunds</strong> = Number of refund events.</li><li><strong>Payouts</strong> = Number of payout events (money sent to instructor bank).</li><li><strong>Transactions</strong> = Total count of all ledger rows (payments + refunds + payouts + reversals, etc.).</li></ul><p>If you want, we can add a second stat (e.g. “Platform commission” or “Net platform earnings”) that sums only commission and subtracts commission reversed on refunds.</p>',36)])])}const p=o(n,[["render",a]]);export{h as __pageData,p as default};
